j:jelly.g2:evaluate:
var gr = new GlideRecord('cmdb_data_classification_mapping');
var hasWriteAccess = gr.canWrite();
var isNewRecord = current.isNewRecord();
var showToolbar = !isNewRecord $[AND] hasWriteAccess;

j2:if.script:
		  var SecurityTagsToolbar = (function() {
			  var listeners = [];
			  var isManual = false;
			  return { 
				addListener: function (fn) {
				  if (typeof fn === "function") {
					listeners.push(fn);
				  }
				},
		        rebuild: function(){
		  			if(!isManual){
						for (var i = 0; i ${AMP}lt; listeners.length; i++) {
							listeners[i]();
						}
		  			}
		  			isManual = false;
		  		},
		        isManual: function(manual){
		  			isManual = manual;
		  		}
			  };
			})();

          addLoadEvent(function() {
              if(typeof angular == 'undefined')
                  return;

			  var security_tag_module = angular.module("securityTagToolbarApp", []);

		      security_tag_module.directive("select", function() {
                  return {
                    restrict: "E",
                    require: "?ngModel",
                    scope: false,
                    link: function (scope, element, attrs, ngModel) {
                      if (!ngModel) {
                        return;
                      }
                      element.bind("keyup", function() {
                        element.triggerHandler("change");
                      })
                    }
                 }
              });

              security_tag_module.controller("securityTagToolbarController", function($scope) {
                  $scope.data = {};

                  // public methods
                  $scope.manageTags = function(newTagId) {
					  if (!newTagId)
						  newTagId = $scope.data.selectedTag.id;
                      if (!newTagId)
                          return;
					  //console.log(newTagId);
                      var recordSysId = g_form.getUniqueValue();
                      var recordTableName = g_form.getTableName();

                      var ajax = new GlideAjax("ClassficationTagUtilAjax");
                      ajax.addParam("sysparm_name", "manageSecurityTagOnRecordAjax");
                      ajax.addParam("sysparm_securityTagId", newTagId);
                      ajax.addParam("sysparm_recordId", recordSysId);
                      ajax.addParam("sysparm_table", recordTableName);
					  //ajax.addParam("sysparm_macro", "macro");
                      ajax.getXMLAnswer( function(rawData) {
                          if (rawData != null $[AMP]$[AMP] rawData != '') {
                              var responseData = JSON.parse(rawData);
                              if (responseData.status === 'ok') {
		  						  SecurityTagsToolbar.isManual(true);
                                  loadAppliedSecurityTags(recordSysId, recordTableName);
                              }
                          }
                      });
					  $scope.data.selectedTag = null;
                  };

				  $scope.removeTag = function(appliedTag, event) {
					  if (!appliedTag || !appliedTag.sys_id)
						  return;

					  if (event) {
						  if (!appliedTag.hasFocus)
							  return;
						  if (event.which !== 46 $[AMP]$[AMP] event.which !== 8)
							  return;
					  }

					  $scope.manageTags(appliedTag.sys_id);
				  };

                  // private methods
                  function loadAppliedSecurityTags(recordSysId, recordTableName) {
                      var ajax = new GlideAjax("ClassficationTagUtilAjax");
                      ajax.addParam("sysparm_name", "getSecurityTagsByRecordAjax");
                      ajax.addParam("sysparm_recordId", recordSysId);
                      ajax.addParam("sysparm_table", recordTableName);
                      ajax.getXMLAnswer( function(rawData) {
                          if (rawData != null $[AMP]$[AMP] rawData != '') {
                              var responseData = JSON.parse(rawData);
                              if (responseData.status === 'ok') {
                                  $scope.$apply(function () {
                                      $scope.data.appliedTags = responseData.content != null ? responseData.content : [];
                                  });
                              }
                          }
                      });
                  };

                  function loadSecurityTagList() {
                      var selectableTags = [];
                      var ajax = new GlideAjax("ClassficationTagUtilAjax");
                      ajax.addParam("sysparm_name", "getSecurityTagMap");
                      ajax.getXMLAnswer( function(rawData) {
                          if (rawData != null $[AMP]$[AMP] rawData != '') {
                              var responseData = JSON.parse(rawData);
                              if (responseData.status === 'ok') {
                                  var content = responseData.content;
                                  for (var property in content) {
                                      if (content.hasOwnProperty(property)) {
                                          for (var i = 0; i ${AMP}lt; (content[property]).length; i++) {
                                              var tag = (content[property])[i];
                                              selectableTags.push({'id': tag.sys_id, 'name': tag.name, 'group': property});
                                          }
                                      }
                                  }
                              }
                          }
                          $scope.$apply(function () {
                              if (selectableTags != null)
                                  $scope.data.availableTags = selectableTags;
                          });
                      });
                  };

		  		  function refreshToolbar(){
		  			loadAppliedSecurityTags(g_form.getUniqueValue(), g_form.getTableName());
		  		  };

		  		  SecurityTagsToolbar.addListener(refreshToolbar);

                  // onload
                  loadSecurityTagList();
                  loadAppliedSecurityTags(g_form.getUniqueValue(), g_form.getTableName());
              });
              angular.element(document).ready(function() {
                  var template = document.getElementById("securityTagToolbarTemplate");
                  var appDiv = document.getElementById("securityTagToolbarApp");
                  setTimeout(function() {
                      appDiv.innerHTML = template.innerHTML;
                      angular.element(appDiv).data('$injector', '');
                      angular.bootstrap(angular.element(appDiv), ['securityTagToolbarApp']);
                  }, 0);
              });
          });
